    {
      "id": "c2",
      "text": "Credibility checks include calibration probes with a lane C held out to guard against contrarianism.",
      "citation_ids": ["S1"]
    },
    {
      "id": "c3",
      "text": "The evaluation includes pushy-user-resistance tests in the model lab using blind human rating.",
      "citation_ids": ["S1"]
    },
    {
      "id": "c4",
      "text": "General-ability spot-checks are performed to confirm no capability collapse occurs during normal tasks.",
      "citation_ids": ["S1"]
    },
    {
      "id": "c5",
      "text": "The deliverable for the credibility evaluation is an eval report containing all four checks.",
      "citation_ids": ["S1"]
    }
  ]
}

